class Solution{int[][]s=new int[10][10];boolean[]v=new boolean[10];int f(int cur,int left){if(left==0)return 1;v[cur]=true;int r=0;for(int x=1;x<=9;x++)if(!v[x]&&(s[cur][x]==0||v[s[cur][x]]))r+=f(x,left-1);v[cur]=false;return r;}public int numberOfPatterns(int m,int n){int[][]p={{1,3,2},{1,7,4},{3,9,6},{7,9,8},{1,9,5},{3,7,5},{4,6,5},{2,8,5}};for(int[]x:p)s[x[0]][x[1]]=s[x[1]][x[0]]=x[2];int r=0;for(int l=m;l<=n;l++)r+=4*f(1,l-1)+4*f(2,l-1)+f(5,l-1);return r;}}
